fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    debug_assert!(len > 0, "input list must be non-empty");

    // Rotation amount is applied modulo len.
    let r = n % len;

    // s = len - (n mod len)
    let s = len - r;

    // Result = list[s..len] + list[0..s]
    let mut new_list = Vec::with_capacity(len);
    new_list.extend_from_slice(&list[s..]);
    new_list.extend_from_slice(&list[..s]);
    new_list
}